CREATE TABLE IF NOT EXISTS recruitment_requisitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position_id uuid REFERENCES org_positions(id) NOT NULL, requisition_title text NOT NULL, jurisdiction text NOT NULL DEFAULT 'Nigeria', priority text NOT NULL DEFAULT 'Normal', employment_type text NOT NULL DEFAULT 'Full-time', hiring_manager text, target_start_date date, status text NOT NULL DEFAULT 'Planned', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS institutional_knowledge (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, category text NOT NULL, owner text, jurisdiction text NOT NULL DEFAULT 'Continental', access_level text NOT NULL DEFAULT 'Internal', summary text, source_reference text, review_date date, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());